import {sheetSVG} from './diagram.mjs?v=20261024';
import {formatMeasurement,formatArea,unitInfo} from './units.mjs?v=20261024';
import {dimensionsText,sheetStats,bandTotals,stockUsage} from './workspace.mjs?v=20261024';
export function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export async function svgImage(svg){const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('The diagram could not be rendered.'));image.src=url;});return image;}finally{URL.revokeObjectURL(url);}}
export async function canvasBlob(canvas,type='image/png'){return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('The browser could not create the image.')),type,.94));}
export function wrapCanvasText(ctx,value,maxWidth){
 const lines=[];for(const paragraph of String(value).split(/\r?\n/)){let line='';for(const word of paragraph.split(/\s+/)){const next=line?line+' '+word:word;if(ctx.measureText(next).width<=maxWidth){line=next;continue;}if(line){lines.push(line);line='';}for(const char of word){if(line&&ctx.measureText(line+char).width>maxWidth){lines.push(line);line='';}line+=char;}}lines.push(line);}return lines;
}
export async function exportSheetPNG(group,project,view,name,options={}){
 const svg=sheetSVG(group.sheet,project,{...view,interactive:false,prefix:'png'}),image=await svgImage(svg),canvas=document.createElement('canvas');
 const box=svg.match(/viewBox="([^"]+)"/)[1].split(' ').map(Number),aspect=box[2]/box[3];
 canvas.width=2400;canvas.height=2400;const ctx=canvas.getContext('2d'),font={normal:28,big:34,huge:40}[options.font]||28;
 ctx.font=`${font}px system-ui`;const notes=wrapCanvasText(ctx,options.notes||'',2280),noteHeight=options.notes?notes.length*font*1.4+30:0;
 const imageH=Math.min(2400,2280/aspect);canvas.height=Math.ceil(190+imageH+noteHeight);
 const drawW=imageH*aspect;ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#25334a';ctx.font=`bold ${font+8}px system-ui`;ctx.fillText(options.header||project.name||'Cutting plan',60,60,2280);ctx.font=`${font}px system-ui`;ctx.fillText(`Sheet ${group.index+1}${group.count>1?` × ${group.count}`:''}${options.date?' · '+new Date().toLocaleDateString():''}`,60,110,2280);ctx.drawImage(image,(2400-drawW)/2,145,drawW,imageH);
 ctx.font=`${font}px system-ui`;notes.forEach((line,i)=>ctx.fillText(line,60,180+imageH+i*font*1.4));downloadBlob(await canvasBlob(canvas),name+'.png');
}
export async function exportReportPDF(project,result,groups,options,view,onProgress=()=>{}){
 const width=1800,height=options.paper==='letter'?1391:1273,margin=78,font={normal:23,big:28,huge:34}[options.font]||23,line=font*1.5;
 const pages=[];let canvas,ctx,y,pageNumber=0;
 const finish=async()=>{if(!canvas)return;pages.push(new Uint8Array(await (await canvasBlob(canvas,'image/jpeg')).arrayBuffer()));if(pages.length>250)throw new Error('This report exceeds 250 pages. Export selected layouts or turn off the cuts table.');onProgress(pages.length);};
 const page=async title=>{await finish();canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,width,height);ctx.fillStyle='#25334a';ctx.font='bold 35px system-ui';ctx.fillText(options.header||project.name||'Cutting plan',margin,70,width-margin*2);ctx.font='24px system-ui';ctx.fillStyle='#66748a';ctx.fillText(title,margin,115,width-margin*2);ctx.font='18px system-ui';ctx.fillText(`${options.date?new Date().toLocaleDateString()+' · ':''}Page ${++pageNumber}`,margin,height-35);ctx.fillText('Verify dimensions, kerf, grain, and cutting order before cutting.',margin+340,height-35);y=175;};
 const text=async(value,bold=false)=>{ctx.font=`${bold?'bold ':''}${font}px system-ui`;const lines=wrapCanvasText(ctx,value,width-margin*2);for(const row of lines){if(y>height-100)await page('Continued');ctx.font=`${bold?'bold ':''}${font}px system-ui`;ctx.fillStyle='#35465c';ctx.fillText(row,margin,y);y+=line;}};
 const settings=project.settings,fmt=n=>formatMeasurement(n,settings.unit,settings.precision),area=n=>formatArea(n,settings.unit,settings.precision),dim=(l,w)=>dimensionsText(l,w,settings);
 if(options.summary){await page('Project summary · all stock and enabled parts');await text(`${result.sheets.length} stock sheets · ${result.sheets.reduce((n,s)=>n+s.parts.length,0)} pieces placed · ${result.unplaced.length} unplaced`,true);await text(`Used: ${area(result.usedArea)} (${result.utilization.toFixed(1)}%) · Unused: ${area(result.stockArea-result.usedArea)}`);await text(`${result.cutCount} cuts · Total cut length: ${fmt(result.cutLength)} ${unitInfo(settings.unit).label}`);await text(`Kerf: ${fmt(settings.kerf)} · Edge trim: ${fmt(settings.trim)} · Minimum trim width: ${fmt(settings.minTrim||0)}`);await text('Stock used',true);for(const s of stockUsage(result))await text(`${s.label||'Stock'} · ${dim(s.length,s.width)} · ${s.material||'No material'} · quantity ${s.used}`);const bands=bandTotals(project.parts);if(bands.length){await text('Edge banding required for all enabled parts',true);for(const b of bands)await text(`${b.name}: ${fmt(b.length)} ${unitInfo(settings.unit).label}`);}if(options.notes)await text(options.notes);if(result.unplaced.length){await text('Unplaced pieces',true);const missing=new Map();for(const p of result.unplaced){const item=missing.get(p.id)||{...p,count:0};item.count++;missing.set(p.id,item);}for(const p of missing.values())await text(`${p.label||'Part'} · ${dim(p.length,p.width)} · quantity ${p.count}`);}}
 for(const group of groups){const s=group.sheet,stats=sheetStats(s);await page(`Sheet ${group.index+1}${group.count>1?` · repeat this layout ${group.count} times`:''} · ${s.label||'Stock'} · ${dim(s.length,s.width)}`);await text(`${stats.pieces} pieces · ${stats.utilization.toFixed(1)}% used · ${stats.cuts} cuts · ${fmt(stats.cutLength)} ${unitInfo(settings.unit).label} cut length`);const svg=sheetSVG(s,project,{...view,interactive:false,prefix:'report'+group.index}),image=await svgImage(svg),box=svg.match(/viewBox="([^"]+)"/)[1].split(' ').map(Number);const imageW=width-margin*2,imageH=height-y-130,rotation=((view.rotation||0)%180)!==0;const ratio=box[2]/box[3],w=Math.min(imageW,imageH*ratio),h=w/ratio;ctx.drawImage(image,margin+(imageW-w)/2,y+15,w,h);if(!options.summary&&options.notes){ctx.font='18px system-ui';ctx.fillText(options.notes.replace(/\s+/g,' '),margin,height-75,width-margin*2);}
  if(options.cuts&&s.cuts.length){await page(`Cut sequence · sheet ${group.index+1}${group.count>1?` × ${group.count}`:''}`);await text('Trim the sheet first. X/Y locate the start of the blade kerf from the original top-left corner.');for(const [i,c] of s.cuts.entries()){const source=c.source?dim(c.source.w,c.source.h):'—',output=c.outputs?.map(p=>dim(p.w,p.h)).join(' + ')||'—';await text(`${i+1}. ${c.axis==='vertical'?'Vertical':'Horizontal'} · X ${fmt(c.x)}, Y ${fmt(c.y)} · length ${fmt(c.length)}` ,true);await text(`From ${source} → ${output}`);}}
 }
 await finish();downloadBlob(buildImagePDF(pages,width,height,options.paper),options.filename+'.pdf');
}
export function buildImagePDF(images,width,height,paper='a4'){
 const encoder=new TextEncoder(),chunks=[],offsets=[0];let length=0;const push=value=>{const bytes=typeof value==='string'?encoder.encode(value):value;chunks.push(bytes);length+=bytes.length;};
 const object=(id,body)=>{offsets[id]=length;push(`${id} 0 obj\n`);push(body);push('\nendobj\n');};
 push('%PDF-1.4\n');object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,`<< /Type /Pages /Count ${images.length} /Kids [${images.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);
 const pw=paper==='letter'?792:841.89,ph=paper==='letter'?612:595.28;
 images.forEach((data,i)=>{const id=3+i*3;object(id,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im${i} ${id+1} 0 R >> >> /Contents ${id+2} 0 R >>`);offsets[id+1]=length;push(`${id+1} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${data.length} >>\nstream\n`);push(data);push('\nendstream\nendobj\n');const content=`q ${pw} 0 0 ${ph} 0 0 cm /Im${i} Do Q`;object(id+2,`<< /Length ${encoder.encode(content).length} >>\nstream\n${content}\nendstream`);});
 const start=length;push(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);for(const offset of offsets.slice(1))push(`${String(offset).padStart(10,'0')} 00000 n \n`);push(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'});
}
